#include <vector>
#include <unordered_map>

long long count_pairs_divisible(std::vector<int> nums, int k) {
    std::unordered_map<int, long long> seen;
    long long count = 0;
    for (int x : nums) {
        int r = ((x % k) + k) % k;
        auto it = seen.find((k - r) % k);
        if (it != seen.end()) count += it->second;
        ++seen[r];
    }
    return count;
}
